import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = [row for row in reader if row and any(cell.strip() for cell in row)]

    if not records:
        return {"columns": [], "rows": []}

    header_markers = {
        "hitid", "hittypeid", "title", "description", "reward",
        "assignmentid", "workerid", "assignmentstatus",
    }

    header_index = None
    best_score = 0
    for index, row in enumerate(records):
        names = [cell.strip().lstrip("\ufeff").lower() for cell in row]
        score = sum(name in header_markers for name in names)
        if score > best_score and score >= 2:
            best_score = score
            header_index = index

    if header_index is None:
        header_index = 0

    columns = [cell.lstrip("\ufeff") for cell in records[header_index]]
    width = len(columns)
    rows = []

    for record in records[header_index + 1:]:
        values = list(record)
        if len(values) < width:
            values.extend([""] * (width - len(values)))
        elif len(values) > width:
            values = values[:width - 1] + [",".join(values[width - 1:])]
        rows.append(values)

    return {"columns": columns, "rows": rows}
